package com.smartring.app.sync.pairing

import java.security.SecureRandom

/**
 * The shared code two phones need before they will talk to each other.
 *
 * Eight digits, generated by one phone and typed into the other. Generated rather than
 * chosen by the user because people choose 12345678; typed rather than scanned or sent
 * because *typing it is the proof that a human has both phones in front of them*.
 *
 * Eight digits is only about 26 bits, which would be hopeless if it had to resist offline
 * guessing on its own. It does not: it is stretched (PBKDF2) and mixed into an ephemeral key
 * exchange, an attacker gets one live attempt per connection, the code dies after
 * [PairingCodeSession.maxAttempts] wrong tries, and it expires after a few minutes. See
 * `PairingProtocol` for the reasoning.
 */
object PairingCodes {
    const val LENGTH = 8

    fun generate(random: SecureRandom = SecureRandom()): String =
        buildString { repeat(LENGTH) { append(random.nextInt(10)) } }

    /**
     * What the user typed, reduced to the eight digits — or null if it is not a code.
     * Tolerates the spaces and dashes people add to read a long number back, and any script's
     * digits (a Hebrew or Arabic keyboard layout may produce them), but nothing else.
     */
    fun normalize(input: String): String? {
        val sb = StringBuilder()
        for (ch in input) {
            when {
                ch.isWhitespace() || ch == '-' || ch == '–' || ch == '‑' -> Unit
                ch.isDigit() -> sb.append(ch.digitToInt())
                else -> return null
            }
        }
        return sb.toString().takeIf { it.length == LENGTH }
    }

    /** "1234 5678" — easier to read aloud and to compare than eight digits in a row. */
    fun format(code: String): String = if (code.length == LENGTH) "${code.take(4)} ${code.drop(4)}" else code
}

/**
 * One code's lifetime on the phone that displays it: usable for a few minutes, for a few
 * wrong guesses, and exactly once.
 *
 * Separate from the handshake on purpose: the handshake reports *that* a joiner got the code
 * wrong, and this decides what that costs. A single connection attempt is cheap for an
 * attacker, so the limit has to live above the connection.
 */
class PairingCodeSession(
    val code: String,
    private val clock: () -> Long = System::currentTimeMillis,
    val ttlMillis: Long = DEFAULT_TTL_MILLIS,
    val maxAttempts: Int = DEFAULT_MAX_ATTEMPTS,
) {
    private val createdAt = clock()

    var attemptsLeft: Int = maxAttempts
        private set

    var consumed: Boolean = false
        private set

    val isExpired: Boolean get() = clock() - createdAt > ttlMillis

    /** Whether a connection should still be allowed to try this code. */
    val isUsable: Boolean get() = !consumed && attemptsLeft > 0 && !isExpired

    val remainingMillis: Long get() = (ttlMillis - (clock() - createdAt)).coerceAtLeast(0L)

    fun recordWrongCode() { if (attemptsLeft > 0) attemptsLeft-- }

    /** A code that has worked once never works again, whatever else is still true of it. */
    fun recordSuccess() { consumed = true }

    companion object {
        const val DEFAULT_TTL_MILLIS = 3 * 60 * 1000L
        const val DEFAULT_MAX_ATTEMPTS = 3
    }
}
